```python
def connected_components(graph):
    seen, components = set(), []
    for start in graph:
        if start in seen: continue
        component, stack = [], [start]; seen.add(start)
        while stack:
            v=stack.pop(); component.append(v)
            for u in graph[v]:
                if u not in seen: seen.add(u); stack.append(u)
        components.append(component)
    return components

assert len(connected_components({0:[1],1:[0],2:[],3:[4],4:[3]})) == 3
